function Get-InfobloxSchema {[CmdletBinding()]param();$script:SchemaCalls++;switch($script:SchemaMode){'present'{@{owned='schema'}}'empty'{$null}'warning'{Write-Warning 'offline-schema';$null}'throw'{throw 'offline-schema-throw'}}}
function Hide-SelfSignedCerts {throw 'Certificate bypass forbidden in offline proof'}
function Invoke-InfobloxQuery {throw 'Network query forbidden in offline proof'}
function Set-OfflineSchema {[CmdletBinding()]param([string]$Mode);$script:SchemaMode=$Mode;$script:SchemaCalls=0}
function Get-OfflineState {[CmdletBinding()]param();[pscustomobject]@{config=$script:InfobloxConfiguration;schemaCalls=$script:SchemaCalls;keys=@($PSDefaultParameterValues.Keys|Where-Object {$_ -like 'Invoke-InfobloxQuery:*'}|Sort-Object);sessionType=if($PSDefaultParameterValues['Invoke-InfobloxQuery:WebSession']){$PSDefaultParameterValues['Invoke-InfobloxQuery:WebSession'].GetType().FullName};timeout=$PSDefaultParameterValues['Invoke-InfobloxQuery:TimeoutSec'];uri=$PSDefaultParameterValues['Invoke-InfobloxQuery:BaseUri'];credentialUser=if($PSDefaultParameterValues['Invoke-InfobloxQuery:Credential']){$PSDefaultParameterValues['Invoke-InfobloxQuery:Credential'].UserName}}}
